package com.google.javascript.rhino.jstype;

import com.google.javascript.rhino.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.jstype.JSTypeRegistry.ResolveMode;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Comparator;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class JSType_getTypesUnderInequality_TriageGen1Test {

    /**
     * Test case for when 'that' is a UnionType.
     * It tests the branch: if (that instanceof UnionType)
     * It verifies that it calls getTypesUnderInequality on the union type and swaps the TypePair order.
     */
    @Test
    public void testGetTypesUnderInequality_WithUnionType() {
        JSType thisType = mock(JSType.class);
        UnionType unionType = mock(UnionType.class);

        TypePair mockPair = new TypePair(mock(JSType.class), mock(JSType.class));
        // We need to ensure the swap happens: return new TypePair(p.typeB, p.typeA)
        // Let's define typeA and typeB explicitly
        JSType typeA = mock(JSType.class);
        JSType typeB = mock(JSType.class);
        TypePair originalPair = new TypePair(typeA, typeB);

        // Mock the behavior of the union type's call
        when(unionType.getTypesUnderInequality(thisType)).thenReturn(originalPair);

        // Execute
        TypePair result = unionType.getTypesUnderInequality(thisType);

        // Verify the swap: result.typeA should be originalPair.typeB, result.typeB should be originalPair.typeA
        assertEquals(typeB, result.typeA);
        assertEquals(typeA, result.typeB);
    }

    /**
     * Test case for when testForEquality returns TRUE.
     * It tests the branch: case TRUE: return new TypePair(null, null);
     */
    @Test
    public void testGetTypesUnderInequality_EqualityTrue() {
        JSType thisType = mock(JSType.class);
        JSType thatType = mock(JSType.class);

        when(thisType.testForEquality(thatType)).thenReturn(TernaryValue.TRUE);

        TypePair result = thisType.getTypesUnderInequality(thatType);

        assertNull(result.typeA);
        assertNull(result.typeB);
    }

    /**
     * Test case for when testForEquality returns FALSE.
     * It tests the branch: case FALSE: return new TypePair(this, that);
     */
    @Test
    public void testGetTypesUnderInequality_EqualityFalse() {
        JSType thisType = mock(JSType.class);
        JSType thatType = mock(JSType.class);

        when(thisType.testForEquality(thatType)).thenReturn(TernaryValue.FALSE);

        TypePair result = thisType.getTypesUnderInequality(thatType);

        assertEquals(thisType, result.typeA);
        assertEquals(thatType, result.typeB);
    }

    /**
     * Test case for when testForEquality returns UNKNOWN.
     * It tests the branch: case UNKNOWN: return new TypePair(this, that);
     */
    @Test
    public void testGetTypesUnderInequality_EqualityUnknown() {
        JSType thisType = mock(JSType.class);
        JSType thatType = mock(JSType.class);

        when(thisType.testForEquality(thatType)).thenReturn(TernaryValue.UNKNOWN);

        TypePair result = thisType.getTypesUnderInequality(thatType);

        assertEquals(thisType, result.typeA);
        assertEquals(thatType, result.typeB);
    }

    /**
     * Test case to cover the IllegalStateException branch.
     * Since TernaryValue is an enum and the switch is exhaustive for the logic,
     * this is technically hard to reach unless TernaryValue has a value not handled.
     * However, we can mock a behavior if we were using a different structure, 
     * but here we assume the switch is exhaustive as per comments.
     * To satisfy coverage requirements for the "throw" line, we assume a scenario 
     * where the switch might fail (though logically impossible with current TernaryValue).
     */
    @Test(expected = IllegalStateException.class)
    public void testGetTypesUnderInequality_ThrowsIllegalStateException() {
        // This test is a placeholder for the "throw" branch.
        // In a real scenario, we'd need to find a way to make the switch fall through.
        // Since we cannot easily mock an enum switch fall-through without bytecode manipulation,
        // and the code says "switch case is exhaustive", this is primarily for structural coverage.
        // If the compiler/runtime allows a null or unexpected value from the mock:
        JSType thisType = mock(JSType.class);
        JSType thatType = mock(JSType.class);

        // This is a hack to attempt to force the exception if the mock returns null
        when(thisType.testForEquality(thatType)).thenReturn(null);

        thisType.getTypesUnderInequality(thatType);
    }
}
